mapper.select:
select count(*) from (
						 select ENTRUST_ID from WFL_ETR_ENTRUST
						 where ENTRUST_ID=#{entrustId}
						 union all
						 select ENTRUST_ID from  WFL_BID_ORDER_BID_PRICE
						 where ENTRUST_ID=#{entrustId}
						 union all
						 select ENTRUST_ID from  BID_ORDER_BID_PRICE
						 where ENTRUST_ID=#{entrustId}
					 )
